SELECT (SELECT COUNT(*) FROM users WHERE DisplayName = 'Tiago Pasqualini') AS n_users,
       (SELECT COUNT(*) FROM posts WHERE OwnerDisplayName = 'Tiago Pasqualini') AS posts_by_owner_displayname,
       (SELECT COUNT(*) FROM posts p JOIN users u ON p.OwnerUserId = u.Id WHERE u.DisplayName = 'Tiago Pasqualini') AS posts_by_owner_join;
